#include <algorithm>
#include <functional>
#include <map>
#include <string>
#include <vector>

class EventBus
{
public:
    int subscribe(const std::string& event, int priority, std::function<void(long long)> handler)
    {
        const int id{ m_nextId++ };
        auto& list{ m_handlers[event] };
        Entry entry{ id, priority, std::move(handler), false };
        // Insert after every entry with priority >= this one: keeps subscription order among equals.
        const auto at{ std::find_if(list.begin(), list.end(), [&](const Entry& e) { return e.priority < priority; }) };
        list.insert(at, std::move(entry));
        return id;
    }

    int publish(const std::string& event, long long value)
    {
        const auto found{ m_handlers.find(event) };
        if (found == m_handlers.end()) return 0;
        ++m_dispatching;
        // Copy the ids to run now: handlers added during this dispatch are not in the list.
        std::vector<int> ids;
        for (const Entry& e : found->second) ids.push_back(e.id);
        int ran{ 0 };
        for (int id : ids)
        {
            Entry* e{ entryFor(event, id) };
            if (!e || e->removed) continue;
            const auto handler{ e->handler };      // copy: the list may change while it runs
            handler(value);
            ++ran;
        }
        if (--m_dispatching == 0) sweep();
        return ran;
    }

    bool unsubscribe(int id)
    {
        for (auto& [event, list] : m_handlers)
            for (Entry& e : list)
                if (e.id == id && !e.removed)
                {
                    e.removed = true;
                    if (m_dispatching == 0) sweep();
                    return true;
                }
        return false;
    }

private:
    struct Entry { int id; int priority; std::function<void(long long)> handler; bool removed; };

    Entry* entryFor(const std::string& event, int id)
    {
        auto& list{ m_handlers[event] };
        for (Entry& e : list) if (e.id == id) return &e;
        return nullptr;
    }

    void sweep()
    {
        for (auto& [event, list] : m_handlers)
            list.erase(std::remove_if(list.begin(), list.end(), [](const Entry& e) { return e.removed; }), list.end());
    }

    std::map<std::string, std::vector<Entry>> m_handlers;
    int m_nextId{ 1 };
    int m_dispatching{ 0 };
};

