#include <vector>
TEST("handlers receive the value") { EventBus bus; long long got{ 0 }; bus.subscribe("died", 0, [&](long long v) { got = v; }); CHECK_EQ(bus.publish("died", 42), 1); CHECK_EQ(got, 42LL); }
TEST("priority order, then subscription order")
{
    EventBus bus; std::vector<int> order;
    bus.subscribe("e", 0, [&](long long) { order.push_back(1); });
    bus.subscribe("e", 5, [&](long long) { order.push_back(2); });
    bus.subscribe("e", 0, [&](long long) { order.push_back(3); });
    bus.subscribe("e", 5, [&](long long) { order.push_back(4); });
    bus.publish("e", 0);
    CHECK(order == std::vector<int>({ 2, 4, 1, 3 }));
}
TEST("other events are not called") { EventBus bus; int calls{ 0 }; bus.subscribe("a", 0, [&](long long) { ++calls; }); CHECK_EQ(bus.publish("b", 0), 0); CHECK_EQ(calls, 0); }
TEST("unsubscribe") { EventBus bus; int calls{ 0 }; const int id{ bus.subscribe("a", 0, [&](long long) { ++calls; }) }; CHECK(bus.unsubscribe(id)); CHECK(!bus.unsubscribe(id)); bus.publish("a", 0); CHECK_EQ(calls, 0); }
TEST("a handler can remove itself")
{
    EventBus bus; int calls{ 0 }; int id{ 0 };
    id = bus.subscribe("a", 0, [&](long long) { ++calls; bus.unsubscribe(id); });
    bus.publish("a", 0); bus.publish("a", 0);
    CHECK_EQ(calls, 1);
}
TEST("removing a later handler during dispatch stops it running")
{
    EventBus bus; int second{ 0 }; int laterId{ 0 };
    bus.subscribe("a", 10, [&](long long) { bus.unsubscribe(laterId); });
    laterId = bus.subscribe("a", 0, [&](long long) { ++second; });
    CHECK_EQ(bus.publish("a", 0), 1);
    CHECK_EQ(second, 0);
}
TEST("handlers added during dispatch wait for the next one")
{
    EventBus bus; int added{ 0 }; bool once{ false };
    bus.subscribe("a", 0, [&](long long) { if (!once) { once = true; bus.subscribe("a", 0, [&](long long) { ++added; }); } });
    bus.publish("a", 0); CHECK_EQ(added, 0);
    bus.publish("a", 0); CHECK_EQ(added, 1);
}

